mapper.select:
SELECT 
FROM scene_execution
WHERE user_id = #{userId}

    AND scene_id = #{sceneId}


    AND trigger_device_id = #{deviceId}


    AND status = #{status}

ORDER BY created_at DESC

mapper.update:
UPDATE scene_execution
SET status = 'SUCCESS',
    finished_at = #{finishedAt,jdbcType=TIMESTAMP},
    updated_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND status IN ('PENDING', 'RUNNING')

mapper.delete:
DELETE FROM scene_execution
WHERE status IN ('SUCCESS', 'FAILED')
  AND finished_at IS NOT NULL
  AND finished_at < #{before,jdbcType=TIMESTAMP}
LIMIT #{limit}
